import{z as A,x as l,o as r,c as C,q as n,j as i,D as E,d as t,s as o,S as T,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"定时器：PIT / HPET / TSC","description":"","frontmatter":{"title":"定时器：PIT / HPET / TSC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timers-tsc-hpet.md","filePath":"cs/timers-tsc-hpet.md","lastUpdated":1791413859000}'),d={name:"cs/timers-tsc-hpet.md"};function P(p,a,c,S,B,m){const s=l("Mermaid");return r(),C("div",null,[a[2]||(a[2]=n('<h1 id="定时器-pit-hpet-tsc" tabindex="-1">定时器：PIT / HPET / TSC <a class="header-anchor" href="#定时器-pit-hpet-tsc" aria-label="Permalink to &quot;定时器：PIT / HPET / TSC&quot;">​</a></h1><div class="epigraph"><p>调度与超时需要时钟源：8253 PIT 是历史滴答，HPET 是平台计数器，TSC 是核上循环计数；谁稳定、谁可同步，决定时间接口怎么接。</p><footer>—— 据 Intel 64 and IA-32 Architectures Software Developer’s Manual；IA-PC HPET Specification；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/apic-interrupt-routing">上一课</a>指出本地 APIC 自带定时器。缺口是平台上<strong>多种时间源</strong>并存：PIT、HPET、ACPI PM、APIC timer、TSC，操作系统如何选时钟事件与时钟源，而不把它们当成同一根线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PIT（8253/8254）：ISA 时代周期滴答，今日遗留。HPET：内存映射比较器，可多路独立中断。TSC：<code>rdtsc</code> 读核内计数器，频率曾随休眠变，后来 invariant TSC 承诺恒定。缺口不是 APIC 路由，而是：<strong>事件（一次性中断）与源（单调计数）</strong> 分离。调度器用事件；时间戳用源。</p><p>校准：用已知 HPET/PIT 间隔量 TSC 频率。跨核 TSC 是否同步是平台属性，VDSO 时钟要小心。</p><h3 id="tsc-不是「墙钟」" tabindex="-1">TSC 不是「墙钟」 <a class="header-anchor" href="#tsc-不是「墙钟」" aria-label="Permalink to &quot;TSC 不是「墙钟」&quot;">​</a></h3><p>墙钟会 NTP 步进；TSC 是单调（在 invariant 前提下）循环计数，换算成纳秒要乘标定因子。把 <code>rdtsc</code> 当 UTC，文件时间戳会错。休眠停核时，非 invariant TSC 会跳，计时器回退是经典 bug。</p><p><span class="marginnote">Intel SDM 描述 TSC 与 APIC timer。HPET 规范描述比较器。Patterson/Hennessy 有设备定时器教学。RISC-V 有 <code>mtime</code>/<code>mtimecmp</code>（CLINT），对照同一分裂：计数 vs 比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动：枚举 HPET、校准 TSC、选 clocksource（TSC 优先若稳定）、选 clockevent（LAPIC 一次性或 HPET）。高精度休眠用单次比较中断，而不是 1000 Hz 节拍——tickless。虚拟化：TSC 偏移与缩放点名。</p>',11)),(r(),i(T,null,{default:E(()=>[o(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TSC%5B%22TSC%20%E8%AE%A1%E6%95%B0%E6%BA%90%22%5D%20--%3E%20NS%5B%22%E6%8D%A2%E7%AE%97%E5%8D%95%E8%B0%83%E6%97%B6%E9%97%B4%22%5D%0A%20%20HPET%5B%22HPET%20%2F%20LAPIC%20%E6%AF%94%E8%BE%83%E5%99%A8%22%5D%20--%3E%20IRQ%5B%22%E6%97%B6%E9%92%9F%E4%B8%AD%E6%96%AD%22%5D%0A%20%20PIT%5B%22PIT%20%E9%81%97%E7%95%99%22%5D%20--%3E%20IRQ%0A%20%20IRQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ADMA%20%E4%B8%8E%E8%AE%BE%E5%A4%87%E6%97%B6%E9%97%B4%E6%97%A0%E5%85%B3%E7%9A%84%E6%90%AC%E8%BF%90%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("与"),e("a",{href:"/cs/reset-strategy"},"复位"),t("后：定时器要重新编程；TSC 在复位后从 0 或保持依平台。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"下一课 DMA 不依赖这些定时器来搬数据，但驱动超时用它们。固件课的引导计时也用 PIT/HPET 早期，因 TSC 标定尚未完成。本课把「时间」从 APIC 单元里拆出来讲清。",-1)),a[6]||(a[6]=e("p",null,"启动早期怎么把 TSC 变成可用的纳秒：",-1)),(r(),i(T,null,{default:E(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOT%5B%22%E5%90%AF%E5%8A%A8%E6%97%A9%E6%9C%9F%22%5D%20--%3E%20REF%5B%22%E7%94%A8%20HPET%20%E6%88%96%20PIT%20%E5%81%9A%E5%B7%B2%E7%9F%A5%E9%97%B4%E9%9A%94%E5%9F%BA%E5%87%86%22%5D%0A%20%20REF%20--%3E%20CAL%5B%22%E5%90%8C%E4%B8%80%E7%AA%97%E5%8F%A3%E5%86%85%E6%95%B0%20TSC%20%E8%B5%B0%E4%BA%86%E5%A4%9A%E5%B0%91%E6%A0%BC%22%5D%0A%20%20CAL%20--%3E%20FREQ%5B%22%E5%BE%97%20TSC%20%E9%A2%91%E7%8E%87%3A%20%E6%A0%87%E5%AE%9A%E5%9B%A0%E5%AD%90%22%5D%0A%20%20FREQ%20--%3E%20USE%7B%22TSC%20invariant%3F%22%7D%0A%20%20USE%20--%3E%7C%22%E6%98%AF%22%7C%20SRC%5B%22%E9%80%89%E4%BD%9C%20clocksource%22%5D%0A%20%20USE%20--%3E%7C%22%E5%90%A6%22%7C%20FALL%5B%22%E9%80%80%E5%9B%9E%20HPET%20%E7%AD%89%E8%BE%83%E6%85%A2%E6%BA%90%22%5D%0A%20%20SRC%20--%3E%20VDSO%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E8%AF%BB%20TSC%20%E4%B9%98%E5%9B%A0%E5%AD%90%E5%BE%97%E7%BA%B3%E7%A7%92%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">术语翻译：「时钟源（clocksource）」回答「现在几点」，给一个只涨不跌的计数；「时钟事件（clockevent）」回答「到点叫我」，在指定时刻发一次中断。TSC 只能当前者；比较器（HPET/LAPIC）才做后者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 NTP 算法，不把 PTP 网卡时钟当必修。不讨论 CPU 频率调节对非 invariant TSC 的全部历史。不进入金融交易所时钟同步。</p><p>后课默认：TSC 适合快时间戳；中断用 LAPIC/HPET 比较器；PIT 是遗留。</p><p><span class="marginnote">数字实例：TSC 一格是 1 个 CPU 周期——3 GHz 的核一秒走 30 亿格，读取只要一条 rdtsc 指令，纳秒级开销；换算成纳秒要乘标定因子，例如约 0.333 纳秒每格。HPET 读一次要走内存映射总线，比 rdtsc 慢一个数量级以上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时钟源（TSC/HPET 计数）与时钟事件（比较中断）分工。</li><li>invariant TSC 才适合做跨休眠的单调源。</li><li>RISC-V <code>mtime</code> 是同一模式的简化。</li><li>出处：Intel SDM；IA-PC HPET Spec；Patterson and Hennessy, COD。</li></ul><p><span class="marginnote">常见误区：初学者容易拿 rdtsc 当墙钟时间——墙钟会被 NTP 拨快拨慢，TSC 只管单调计数；要 UTC 必须经另一套接口换算。休眠停核时非 invariant TSC 还会跳变，计时器「回退」是经典 bug。</span></p>',8))])}const D=A(d,[["render",P]]);export{u as __pageData,D as default};
